mkfn!{
    catch_unwind_introspect!();
    # [doc = " Invokes a closure, capturing the cause of an unwinding panic if one occurs."] # [doc = ""] # [doc = " This function will return `Ok` with the closure's result if the closure does"] # [doc = " not panic, and will return `Err(cause)` if the closure panics. The `cause`"] # [doc = " returned is the object with which panic was originally invoked."] # [doc = ""] # [doc = " Rust functions that are expected to be called from foreign code that does"] # [doc = " not support unwinding (such as C compiled with `-fno-exceptions`) should be"] # [doc = " defined using `extern \"C\"`, which ensures that if the Rust code panics, it"] # [doc = " is automatically caught and the process is aborted. If this is the desired"] # [doc = " behavior, it is not necessary to use `catch_unwind` explicitly. This"] # [doc = " function should instead be used when more graceful error-handling is needed."] # [doc = ""] # [doc = " It is **not** recommended to use this function for a general try/catch"] # [doc = " mechanism. The [`Result`] type is more appropriate to use for functions that"] # [doc = " can fail on a regular basis. Additionally, this function is not guaranteed"] # [doc = " to catch all panics, see the \"Notes\" section below."] # [doc = ""] # [doc = " The closure provided is required to adhere to the [`UnwindSafe`] trait to"] # [doc = " ensure that all captured variables are safe to cross this boundary. The"] # [doc = " purpose of this bound is to encode the concept of [exception safety][rfc] in"] # [doc = " the type system. Most usage of this function should not need to worry about"] # [doc = " this bound as programs are naturally unwind safe without `unsafe` code. If"] # [doc = " it becomes a problem the [`AssertUnwindSafe`] wrapper struct can be used to"] # [doc = " quickly assert that the usage here is indeed unwind safe."] # [doc = ""] # [doc = " [rfc]: https://github.com/rust-lang/rfcs/blob/master/text/1236-stabilize-catch-panic.md"] # [doc = ""] # [doc = " # Notes"] # [doc = ""] # [doc = " This function **might not catch all Rust panics**. A Rust panic is not"] # [doc = " always implemented via unwinding, but can be implemented by aborting the"] # [doc = " process as well. This function *only* catches unwinding panics, not those"] # [doc = " that abort the process."] # [doc = ""] # [doc = " If a custom panic hook has been set, it will be invoked before the panic is"] # [doc = " caught, before unwinding."] # [doc = ""] # [doc = " Although unwinding into Rust code with a foreign exception (e.g. an"] # [doc = " exception thrown from C++ code, or a `panic!` in Rust code compiled or"] # [doc = " linked with a different runtime) via an appropriate ABI (e.g. `\"C-unwind\"`)"] # [doc = " is permitted, catching such an exception using this function will have one"] # [doc = " of two behaviors, and it is unspecified which will occur:"] # [doc = ""] # [doc = " * The process aborts, after executing all destructors of `f` and the"] # [doc = "   functions it called."] # [doc = " * The function returns a `Result::Err` containing an opaque type."] # [doc = ""] # [doc = " Finally, be **careful in how you drop the result of this function**. If it"] # [doc = " is `Err`, it contains the panic payload, and dropping that may in turn"] # [doc = " panic!"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::panic;"] # [doc = ""] # [doc = " let result = panic::catch_unwind(|| {"] # [doc = "     println!(\"hello!\");"] # [doc = " });"] # [doc = " assert!(result.is_ok());"] # [doc = ""] # [doc = " let result = panic::catch_unwind(|| {"] # [doc = "     panic!(\"oh no!\");"] # [doc = " });"] # [doc = " assert!(result.is_err());"] # [doc = " ```"] # [stable (feature = "catch_unwind" , since = "1.9.0")] pub fn catch_unwind < F : FnOnce () -> R + UnwindSafe , R > (f : F) -> Result < R > { unsafe { panicking :: catch_unwind (f) } }
}

