mkfn!{
    get_backtrace_style_introspect!();
    # [doc = " Checks whether the standard library's panic hook will capture and print a"] # [doc = " backtrace."] # [doc = ""] # [doc = " This function will, if a backtrace style has not been set via"] # [doc = " [`set_backtrace_style`], read the environment variable `RUST_BACKTRACE` to"] # [doc = " determine a default value for the backtrace formatting:"] # [doc = ""] # [doc = " The first call to `get_backtrace_style` may read the `RUST_BACKTRACE`"] # [doc = " environment variable if `set_backtrace_style` has not been called to"] # [doc = " override the default value. After a call to `set_backtrace_style` or"] # [doc = " `get_backtrace_style`, any changes to `RUST_BACKTRACE` will have no effect."] # [doc = ""] # [doc = " `RUST_BACKTRACE` is read according to these rules:"] # [doc = ""] # [doc = " * `0` for `BacktraceStyle::Off`"] # [doc = " * `full` for `BacktraceStyle::Full`"] # [doc = " * `1` for `BacktraceStyle::Short`"] # [doc = " * Other values are currently `BacktraceStyle::Short`, but this may change in"] # [doc = "   the future"] # [doc = ""] # [doc = " Returns `None` if backtraces aren't currently supported."] # [unstable (feature = "panic_backtrace_config" , issue = "93346")] pub fn get_backtrace_style () -> Option < BacktraceStyle > { if ! cfg ! (feature = "backtrace") { return None ; } let current = SHOULD_CAPTURE . load (Ordering :: Relaxed) ; if let Some (style) = BacktraceStyle :: from_u8 (current) { return Some (style) ; } let format = match crate :: env :: var_os ("RUST_BACKTRACE") { Some (x) if & x == "0" => BacktraceStyle :: Off , Some (x) if & x == "full" => BacktraceStyle :: Full , Some (_) => BacktraceStyle :: Short , None if crate :: sys :: FULL_BACKTRACE_DEFAULT => BacktraceStyle :: Full , None => BacktraceStyle :: Off , } ; match SHOULD_CAPTURE . compare_exchange (0 , format . as_u8 () , Ordering :: Relaxed , Ordering :: Relaxed) { Ok (_) => Some (format) , Err (new) => BacktraceStyle :: from_u8 (new) , } }
}